#include <stdio.h>

// Write swap function

int main() {
    int a = 5, b = 10;
    // Swap values
    return 0;
}

exercises.solutionCode:
#include <stdio.h>

void swap(int *x, int *y) {
    int temp = *x;
    *x = *y;
    *y = temp;
}

int main() {
    int a = 5, b = 10;
    printf("Before: a=%d, b=%d\n", a, b);
    swap(&a, &b);
    printf("After: a=%d, b=%d\n", a, b);
    return 0;
}

