}

exercises.solutionCode:
#include <stdio.h>
#include <stdlib.h>

int main() {
    int *arr = (int*)calloc(3, sizeof(int)); // Zero-initialized
    if (!arr) return 1;

    arr[0] = 10; arr[1] = 20; arr[2] = 30;

    // Resize array from 3 to 5 elements
    int *temp = (int*)realloc(arr, 5 * sizeof(int));
    if (!temp) {
        free(arr);
        return 1;
    }
    arr = temp;
    arr[3] = 40; arr[4] = 50;

    for (int i = 0; i < 5; i++) printf("%d ", arr[i]);
    printf("\n");

    free(arr);
    return 0;
}

