int main() {
    // Execute bitwise AND, OR, XOR, shifts
    return 0;
}

exercises.solutionCode:
#include <stdio.h>

int main() {
    unsigned char flags = 0; // 0000 0000
    unsigned char READ_FLAG  = 1 << 0; // 0000 0001 (1)
    unsigned char WRITE_FLAG = 1 << 1; // 0000 0010 (2)

    // Set WRITE_FLAG using OR
    flags |= WRITE_FLAG;

    // Test READ_FLAG using AND
    int can_read = (flags & READ_FLAG) != 0;
    int can_write = (flags & WRITE_FLAG) != 0;

    printf("Flags Byte: 0x%02X\n", flags);
    printf("Can Read: %d | Can Write: %d\n", can_read, can_write);
    return 0;
}

