#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct {
    int account_number;
    char holder_name[50];
    double balance;
} Account;

typedef struct {
    Account *accounts;
    int count;
    int capacity;
} BankSystem;

void init_bank(BankSystem *bank) {
    bank->count = 0;
    bank->capacity = 2;
    bank->accounts = (Account*)malloc(bank->capacity * sizeof(Account));
}

void add_account(BankSystem *bank, int acc_num, const char *name, double initial_balance) {
    if (bank->count >= bank->capacity) {
        bank->capacity *= 2;
        bank->accounts = (Account*)realloc(bank->accounts, bank->capacity * sizeof(Account));
    }
    Account *acc = &bank->accounts[bank->count++];
    acc->account_number = acc_num;
    strcpy(acc->holder_name, name);
    acc->balance = initial_balance;
}

void free_bank(BankSystem *bank) {
    free(bank->accounts);
    bank->accounts = NULL;
}

int main() {
    BankSystem bank;
    init_bank(&bank);

    add_account(&bank, 1001, "Alex River", 1500.50);
    add_account(&bank, 1002, "Sarah Smith", 2800.00);

    for (int i = 0; i < bank.count; i++) {
        printf("Account #%d: %s | Balance: $%.2f\n", 
            bank.accounts[i].account_number, 
            bank.accounts[i].holder_name, 
            bank.accounts[i].balance);
    }

    free_bank(&bank);
    return 0;
}
